package local.tvmorph.tv;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.provider.DocumentsContract;
/** System file picker grants access only to the file selected by the user. */
public final class UsbFilesActivity extends Activity {
 @Override public void onCreate(Bundle state){super.onCreate(state);if(state!=null)return;Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"video/*","audio/*","image/*"}).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(Build.VERSION.SDK_INT>=26){String volume=getIntent().getStringExtra("volume");if(volume!=null)pick.putExtra(DocumentsContract.EXTRA_INITIAL_URI,DocumentsContract.buildDocumentUri("com.android.externalstorage.documents",volume+":"));}try{startActivityForResult(pick,671);}catch(ActivityNotFoundException e){try{Intent fallback=new Intent(Intent.ACTION_GET_CONTENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"video/*","audio/*","image/*"}).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(fallback,671);return;}catch(ActivityNotFoundException unavailable){}new AlertDialog.Builder(this).setTitle("USB").setMessage(UiSettings.text(this,"النظام لا يوفر متصفح ملفات للتطبيقات. افتح الفلاشة من مشغّل الوسائط أو مدير الملفات الخاص بالجهاز.","This TV has no system file picker. Open USB using the TV media player or an installed file manager.")).setPositiveButton(UiSettings.text(this,"إعدادات التخزين","Storage settings"),(d,w)->{try{startActivity(new Intent(android.provider.Settings.ACTION_INTERNAL_STORAGE_SETTINGS));}catch(RuntimeException ignored){}finish();}).setNegativeButton(UiSettings.text(this,"رجوع","Back"),(d,w)->finish()).setOnCancelListener(d->finish()).show();}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=671)return;if(result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();if(!"content".equals(uri.getScheme())){finish();return;}String type=getContentResolver().getType(uri);if(type==null||!(type.startsWith("video/")||type.startsWith("audio/")||type.startsWith("image/"))){finish();return;}try{Intent play=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,type).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);play.setClipData(ClipData.newRawUri("USB media",uri));startActivity(Intent.createChooser(play,UiSettings.text(this,"فتح ملف الفلاشة","Open USB media")));}catch(RuntimeException e){android.widget.Toast.makeText(this,UiSettings.text(this,"لا يوجد مشغّل مثبت يدعم الملف المختار.","No installed player supports the selected file."),1).show();}}finish();}
}
